-- Caelestia's keymap (https://github.com/caelestia-dots/caelestia), ported to
-- the commands that exist on this machine.  Caelestia features with no
-- equivalent here (shell panels, lock screen, screen recorder, emoji picker,
-- paste-latest) are intentionally left unbound rather than bound to nothing.

local mainMod = "SUPER" -- Sets "Windows" key as main modifier

-- Super pressed on its own opens the rofi application launcher (with icons).
-- The `release` flag makes it fire when Super is *released*, and the "SUPER +"
-- modifier mask keeps it from stealing the SUPER + <key> combos below.
-- Hyprland shadows this bind as soon as one of those combos fires while Super
-- is held, so pressing Super+E never ends up opening the launcher too.
local launcher = "pkill -x rofi || rofi -show drun -show-icons"
hl.bind("SUPER + Super_L", hl.dsp.exec_cmd(launcher), { release = true, description = "Rofi drun launcher (left Super)" })
hl.bind("SUPER + Super_R", hl.dsp.exec_cmd(launcher), { release = true, description = "Rofi drun launcher (right Super)" })

-- Workspaces: SUPER + 0-9, groups on CTRL + SUPER + 0-9.
-- Caelestia organises workspaces in blocks of ten; moving to "group 2" while
-- on workspace 3 means workspace 13, and so on.
local function ws_action(action, group, i)
    return function()
        local active = hl.get_active_workspace()
        if not active then
            return
        end

        local target
        if group then
            target = (i - 1) * 10 + (active.id % 10)
        else
            target = math.floor((active.id - 1) / 10) * 10 + i
        end

        if action == "move" then
            hl.dispatch(hl.dsp.window.move({ workspace = target }))
        elseif action == "silent" then
            hl.dispatch(hl.dsp.window.move({ workspace = target, follow = false }))
        else
            hl.dispatch(hl.dsp.focus({ workspace = target }))
        end
    end
end

for i = 1, 10 do
    local key = i % 10 -- 10 maps to key 0
    hl.bind(mainMod .. " + " .. key, ws_action("focus", false, i))
    hl.bind("CTRL + SUPER + " .. key, ws_action("focus", true, i))
    hl.bind(mainMod .. " + ALT + " .. key, ws_action("move", false, i))
    hl.bind("CTRL + SUPER + ALT + " .. key, ws_action("move", true, i))
    hl.bind(mainMod .. " + SHIFT + " .. key, ws_action("silent", false, i))
end

-- Holding a key repeats, but scrolling must not rapid-fire workspace switches.
local function repeat_key(key)
    if key:find("mouse", 1, true) then
        return nil
    end
    return { repeating = true }
end

-- Previous / next workspace and workspace group.
local prev_ws = { "SUPER + mouse_up", "CTRL + SUPER + Left", "SUPER + Page_Up" }
local next_ws = { "SUPER + mouse_down", "CTRL + SUPER + Right", "SUPER + Page_Down" }
for _, key in ipairs(prev_ws) do hl.bind(key, hl.dsp.focus({ workspace = "-1" }), repeat_key(key)) end
for _, key in ipairs(next_ws) do hl.bind(key, hl.dsp.focus({ workspace = "+1" }), repeat_key(key)) end
hl.bind("CTRL + SUPER + mouse_up",   hl.dsp.focus({ workspace = "-10" }))
hl.bind("CTRL + SUPER + mouse_down", hl.dsp.focus({ workspace = "+10" }))

-- Move the active window to the previous / next workspace.
local move_prev = { "SUPER + ALT + mouse_up", "SUPER + ALT + Page_Up", "CTRL + SUPER + SHIFT + Left" }
local move_next = { "SUPER + ALT + mouse_down", "SUPER + ALT + Page_Down", "CTRL + SUPER + SHIFT + Right" }
for _, key in ipairs(move_prev) do hl.bind(key, hl.dsp.window.move({ workspace = "-1" }), repeat_key(key)) end
for _, key in ipairs(move_next) do hl.bind(key, hl.dsp.window.move({ workspace = "+1" }), repeat_key(key)) end

-- Special workspace (scratchpad) and moving windows in and out of it.
hl.bind(mainMod .. " + S", hl.dsp.workspace.toggle_special("magic"))
hl.bind(mainMod .. " + ALT + S", hl.dsp.window.move({ workspace = "special:magic" }))
hl.bind("CTRL + SUPER + SHIFT + Up", hl.dsp.window.move({ workspace = "special:magic" }))
hl.bind("CTRL + SUPER + SHIFT + Down", hl.dsp.window.move({ workspace = "e+0" }))

-- Window groups and cycling between windows.
hl.bind("ALT + TAB", hl.dsp.window.cycle_next(), { repeating = true })
hl.bind("SHIFT + ALT + TAB", hl.dsp.window.cycle_next({ next = false }), { repeating = true })
hl.bind("CTRL + ALT + TAB", hl.dsp.group.next(), { repeating = true })
hl.bind("CTRL + SHIFT + ALT + TAB", hl.dsp.group.prev(), { repeating = true })
hl.bind(mainMod .. " + Comma", hl.dsp.group.toggle())
hl.bind(mainMod .. " + SHIFT + Comma", hl.dsp.group.lock_active())
hl.bind(mainMod .. " + U", hl.dsp.window.move({ out_of_group = true }))

-- Focus and move windows with the arrow keys.
for _, dir in ipairs({ "left", "right", "up", "down" }) do
    hl.bind(mainMod .. " + " .. dir, hl.dsp.focus({ direction = dir }))
    hl.bind(mainMod .. " + SHIFT + " .. dir, hl.dsp.window.move({ direction = dir }))
end

-- Keyboard resizing: SUPER + -/= changes width, + SHIFT changes height,
-- SUPER + ALT + arrows does both.
local function resize_by(percent_x, percent_y)
    return function()
        local win = hl.get_active_window()
        if not (win and win.size) then
            return
        end
        hl.dispatch(hl.dsp.window.resize({
            x = math.floor(win.size.x * percent_x / 100),
            y = math.floor(win.size.y * percent_y / 100),
            relative = true,
        }))
    end
end

hl.bind(mainMod .. " + Minus", resize_by(-10, 0), { repeating = true })
hl.bind(mainMod .. " + Equal", resize_by(10, 0), { repeating = true })
hl.bind(mainMod .. " + SHIFT + Minus", resize_by(0, -10), { repeating = true })
hl.bind(mainMod .. " + SHIFT + Equal", resize_by(0, 10), { repeating = true })
hl.bind(mainMod .. " + ALT + Left", resize_by(-10, 0), { repeating = true })
hl.bind(mainMod .. " + ALT + Right", resize_by(10, 0), { repeating = true })
hl.bind(mainMod .. " + ALT + Up", resize_by(0, -10), { repeating = true })
hl.bind(mainMod .. " + ALT + Down", resize_by(0, 10), { repeating = true })

-- Move / resize with the mouse: hold SUPER and drag, or the Z / X modal keys.
hl.bind(mainMod .. " + Z", hl.dsp.window.drag(), { mouse = true })
hl.bind(mainMod .. " + X", hl.dsp.window.resize(), { mouse = true })
hl.bind(mainMod .. " + mouse:272", hl.dsp.window.drag(), { mouse = true })
hl.bind(mainMod .. " + mouse:273", hl.dsp.window.resize(), { mouse = true })

-- Placement: centre, normalise (55% x 70%), picture-in-picture corner.
hl.bind("CTRL + SUPER + Backslash", hl.dsp.window.center())
hl.bind("CTRL + SUPER + ALT + Backslash", function()
    local mon = hl.get_active_monitor()
    if not mon then
        return
    end
    local scale = mon.scale or 1
    hl.dispatch(hl.dsp.window.resize({
        x = math.floor(mon.width / scale * 0.55),
        y = math.floor(mon.height / scale * 0.70),
        relative = false,
    }))
    hl.dispatch(hl.dsp.window.center())
end)
hl.bind(mainMod .. " + ALT + Backslash", function()
    local win = hl.get_active_window()
    local mon = hl.get_active_monitor()
    if not (win and win.size and mon) then
        return
    end
    if not win.floating then
        hl.dispatch(hl.dsp.window.float())
    end

    local scale = mon.scale or 1
    local mon_w, mon_h = mon.width / scale, mon.height / scale
    local factor = (mon_h / 4) / win.size.y
    local w = math.max(200, math.floor(win.size.x * factor))
    local h = math.max(150, math.floor(win.size.y * factor))
    local offset = math.min(mon_w, mon_h) * 0.03

    hl.dispatch(hl.dsp.window.resize({ x = w, y = h, relative = false }))
    hl.dispatch(hl.dsp.window.move({
        x = math.floor(mon.x + mon_w - w - offset),
        y = math.floor(mon.y + mon_h - h - offset),
        relative = false,
    }))
    hl.dispatch(hl.dsp.window.pin({ action = "on" }))
end)

hl.bind(mainMod .. " + P", hl.dsp.window.pin())
hl.bind(mainMod .. " + F", hl.dsp.window.fullscreen({ mode = "fullscreen" }))
hl.bind(mainMod .. " + ALT + F", hl.dsp.window.fullscreen({ mode = "maximized" }))
hl.bind(mainMod .. " + ALT + Space", hl.dsp.window.float())
hl.bind(mainMod .. " + Q", hl.dsp.window.close())
hl.bind(mainMod .. " + J", hl.dsp.layout("togglesplit"))    -- extra: dwindle only

-- System monitor on its own special workspace (btop in a kitty window).
hl.bind("CTRL + SHIFT + Escape", function()
    local active = hl.get_active_special_workspace()
    if active and active.name == "special:sysmon" then
        return hl.dispatch(hl.dsp.workspace.toggle_special("sysmon"))
    end

    local running = false
    for _, win in ipairs(hl.get_windows() or {}) do
        if win.class == "btop" then
            running = true
            break
        end
    end

    hl.dispatch(hl.dsp.focus({ workspace = "special:sysmon" }))
    if not running then
        hl.dispatch(hl.dsp.exec_cmd(terminal .. " --class btop -e btop", { workspace = "special:sysmon" }))
    end
end)

